head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.isUpdate = false;
scwin.storageId = "";

// 수정 여부

///////// 2. 초기화 영역 /////////

/**
 * @method
 * @name onpageload
 * @description 화면 진입점 — 화면 전환 파라미터(storageId)를 수신하고 서식분류(대분류)·상장고시 시장구분 공통코드를 조회해 select box를 구성한다.
 * @returns {void}
 * @hidden N
 * @example (body ev:onpageload 바인딩으로 자동 호출)
 */
scwin.onpageload = async function() {
    scwin.storageId = $c.data.getParameter("storageId");

    // 상장고시 시장구분코드
    const list = ["LD_MKT_TP_CD"];
    const params = {"cdEngNmList":list};

    // 서식분류 정보 조회
    const sbmOptions = {
        id : "sbm_upclss",
        action : "/api/code/form-upclss",
        method : "get",
        processMsg : "공통코드 조회중..."
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    scwin.sbm_upclss_submitdone(sbmRtn);

    // 시장구분 정보 조회
    $c.sbm.execute(sbm_ldMktTpCd, params);
};

///////// 3. 컴포넌트 이벤트 영역 /////////

/**
 * @method
 * @name ibx_rsnClssCd_onkeyup
 * @description 사유분류코드 입력 키업 — 한글 입력을 차단하고 숫자(양수)만 입력되도록 값을 보정한다.
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 * @example scwin.ibx_rsnClssCd_onkeyup(e);
 */
scwin.ibx_rsnClssCd_onkeyup = function (e) {
    $c.tms.disableBlockKor(ibx_rsnClssCd);
    // 양수만 되게 수정
    ibx_rsnClssCd.setValue((ibx_rsnClssCd.getValue()).replace(/[^0-9]/g, ""));
};

/**
 * @method
 * @name ibx_disclsRsnClssEngNm_onkeyup
 * @description 사유분류영문명 입력 키업 — 한글 입력을 차단한다.
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 * @example scwin.ibx_disclsRsnClssEngNm_onkeyup(e);
 */
scwin.ibx_disclsRsnClssEngNm_onkeyup = function (e) {
    $c.tms.disableBlockKor(ibx_disclsRsnClssEngNm);
};

/**
 * @method
 * @name btn_save_onclick
 * @description [저장] 버튼 클릭 — 입력 그룹(grp_input) validation 체크 후, 변경 모드면 update 액션으로 전환하고 사유분류 정보를 저장한다(이중 클릭 방지 포함).
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 * @example scwin.btn_save_onclick(e);
 */
scwin.btn_save_onclick = async function (e) {
    // validation 체크
    if (!$c.tms.validateGroupTms("grp_input")) return;

    if (scwin.isUpdate) {
        $c.sbm.setAction(sbm_save, "/api/code/rsn-clss/update/" + dma_save.get("formUpclssCd") + "/" + dma_save.get("rsnClssCd") + "/" + dma_save.get("ldMktTpCd"));
    }
    // 이중 클릭 방지
    btn_save.setDisabled(true);
    // 정보 저장
    $c.sbm.execute(sbm_save, dma_save.getJSON());
};

/**
 * @method
 * @name btn_close_onclick
 * @description [취소] 버튼 클릭 — 팝업을 닫는다.
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 * @example scwin.btn_close_onclick(e);
 */
scwin.btn_close_onclick = function (e) {
    $c.win.closePopup();
};

///////// 4. 서브미션 콜백 영역 /////////

/**
 * @method
 * @name sbm_upclss_submitdone
 * @description sbm_upclss(동적 서브미션) 콜백 — 조회 성공 시 서식대분류 select box를 자동 생성하고, 실패 시 메시지를 알린다.
 * @param {Object} e 서브미션 응답 객체
 * @returns {void}
 * @hidden N
 * @example scwin.sbm_upclss_submitdone(sbmRtn);
 */
scwin.sbm_upclss_submitdone = function (e) {
    // 조회 성공인 경우
    const result = e.responseJSON;
    if (result.success) {
        // select box 자동 생성
        $c.tms.setSelectData(result.body, sbx_formUpclssCd, "formUpclssNm", "formUpclssCd");
    } else {
        $c.win.alert(result.message);
    }
};

/**
 * @method
 * @name sbm_ldMktTpCd_submitdone
 * @description sbm_ldMktTpCd 콜백 — 조회 성공 시 시장구분 select box를 자동 생성하고, 실패 시 메시지를 알린다. 이후 파라미터(formUpclssCd) 수신 시 지연 처리로 변경 모드로 전환한다(키 항목 비활성·버튼명 변경).
 * @param {Object} e 서브미션 응답 객체
 * @returns {void}
 * @hidden N
 * @example (sbm_ldMktTpCd ev:submitdone 바인딩으로 자동 호출)
 */
scwin.sbm_ldMktTpCd_submitdone = function (e) {
    // 조회 성공인 경우
    const result = e.responseJSON;
    if (result.success) {
        // select box 자동 생성
        $c.tms.setSelectData(result.body, sbx_ldMktTpCd, "cdValNm", "cdVal", "LD_MKT_TP_CD", "cdEngNm");
    } else {
        $c.win.alert(result.message);
    }

    setTimeout(function () {
        const formUpclssCd = $c.data.getParameter("formUpclssCd");
        if (!$c.util.isEmpty(formUpclssCd)) {
            dma_save.set("formUpclssCd", formUpclssCd);
            dma_save.set("rsnClssCd", $c.data.getParameter("rsnClssCd"));
            dma_save.set("ldMktTpCd", $c.data.getParameter("ldMktTpCd"));
            dma_save.set("disclsRsnClssNm", $c.data.getParameter("disclsRsnClssNm"));
            dma_save.set("disclsRsnClssEngNm", $c.data.getParameter("disclsRsnClssEngNm"));

            sbx_formUpclssCd.setDisabled(true);
            ibx_rsnClssCd.setDisabled(true);
            sbx_ldMktTpCd.setDisabled(true);
            btn_save.setValue("변경 저장");
            scwin.isUpdate = true;
        }
    }, 100);
};

/**
 * @method
 * @name sbm_save_submitdone
 * @description sbm_save 콜백 — 저장 성공 시 완료 메시지 후 refreshYn·storageId 를 담아 팝업을 닫고, 실패 시 메시지를 알린다(이중 클릭 해제 포함).
 * @param {Object} e 서브미션 응답 객체
 * @returns {void}
 * @hidden N
 * @example (sbm_save ev:submitdone 바인딩으로 자동 호출)
 */
scwin.sbm_save_submitdone = async function (e) {
    const result = e.responseJSON;
    if (result.success) {
        await $c.win.alert("저장 되었습니다.");

        const params = {};
        params.refreshYn = "Y";
        params.storageId = scwin.storageId;

        $c.win.closePopup(params);
    } else {
        $c.win.alert(result.message);
    }
    // 이중 클릭 해제
    btn_save.setDisabled(false);
};
